begin;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'easy', body = 'The touchscreen of a smartphone is:', body_hi = 'स्मार्टफ़ोन की टचस्क्रीन है:', explanation = 'A touchscreen displays images, so it is an output device like a monitor, and senses where a finger touches it, so it is an input device like a keyboard or mouse. A headset with a microphone is also both; a printer is only output, a keyboard only input, and flash memory is storage.', explanation_hi = 'टचस्क्रीन चित्र दिखाती है, इसलिए वह मॉनिटर की तरह आउटपुट उपकरण है, और यह भाँपती है कि उँगली कहाँ छू रही है, इसलिए वह कीबोर्ड या माउस की तरह इनपुट उपकरण है। माइक्रोफ़ोन वाला हेडसेट भी दोनों है; प्रिंटर केवल आउटपुट है, कीबोर्ड केवल इनपुट, और फ़्लैश मेमोरी भंडारण है।', concept_group_id = 'it-input-device-easy', source_citation = 'NCERT Class XI Computer Science (Computer System).', question_data = '{"craft": "application"}'::jsonb, options = '[{"id": "a", "body": "only an input device", "body_hi": "केवल इनपुट उपकरण", "isCorrect": false}, {"id": "b", "body": "only an output device", "body_hi": "केवल आउटपुट उपकरण", "isCorrect": false}, {"id": "c", "body": "both an input and an output device", "body_hi": "इनपुट और आउटपुट दोनों उपकरण", "isCorrect": true}, {"id": "d", "body": "a storage device that keeps the user''s files", "body_hi": "उपयोगकर्ता की फ़ाइलें रखने वाला भंडारण उपकरण", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-input-device-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'easy', body = 'Which one of the following statements about the internet and the World Wide Web is correct?', body_hi = 'इंटरनेट और वर्ल्ड वाइड वेब के बारे में निम्नलिखित में से कौन-सा कथन सही है?', explanation = 'The internet is the worldwide network of networks, growing out of the ARPANET of 1969 and the TCP/IP standards of the early 1980s. The World Wide Web, invented by Tim Berners-Lee in 1989, is one service that runs on it: pages linked by hyperlinks and fetched with HTTP, which is what ''www'' addresses point to. Email, file transfer, video calls and many apps are other internet services that do not need the Web.', explanation_hi = 'इंटरनेट नेटवर्कों का विश्वव्यापी नेटवर्क है, जो 1969 के ARPANET और 1980 के दशक के आरंभ के TCP/IP मानकों से विकसित हुआ। टिम बर्नर्स-ली द्वारा 1989 में आविष्कृत वर्ल्ड वाइड वेब उस पर चलने वाली एक सेवा है: हाइपरलिंक से जुड़े और HTTP से प्राप्त किए जाने वाले पृष्ठ, जिनकी ओर ''www'' पते इंगित करते हैं। ईमेल, फ़ाइल स्थानांतरण, वीडियो कॉल और अनेक ऐप अन्य इंटरनेट सेवाएँ हैं जिन्हें वेब की आवश्यकता नहीं होती।', concept_group_id = 'it-www-easy', source_citation = 'NCERT Class XII Computer Science (Computer Networks).', question_data = '{"craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "The Web is a system of linked pages running on the internet", "body_hi": "वेब जुड़े हुए पृष्ठों की एक प्रणाली है जो इंटरनेट पर चलती है", "isCorrect": true}, {"id": "b", "body": "The internet and the Web are two names for the same network", "body_hi": "इंटरनेट और वेब एक ही नेटवर्क के दो नाम हैं", "isCorrect": false}, {"id": "c", "body": "The Web is older than the internet, which grew out of it", "body_hi": "वेब इंटरनेट से पुराना है, और इंटरनेट उसी से विकसित हुआ", "isCorrect": false}, {"id": "d", "body": "Email can work only through the pages of the World Wide Web", "body_hi": "ईमेल केवल वर्ल्ड वाइड वेब के पृष्ठों के माध्यम से काम करता है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-www-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'medium', body = 'Many websites have replaced CAPTCHAs that ask users to type distorted letters with other checks. The main reason is that:', body_hi = 'अनेक वेबसाइटों ने विकृत अक्षर टाइप करवाने वाले CAPTCHA की जगह अन्य जाँचें अपना ली हैं। इसका मुख्य कारण यह है कि:', explanation = 'A CAPTCHA -- a ''Completely Automated Public Turing test to tell Computers and Humans Apart'' -- works only while its task is easy for people and hard for machines. Image recognition has made distorted text easy for bots, so sites have moved to picture puzzles and, increasingly, to invisible checks of how a user moves the mouse, types and browses; the contest continues as AI improves.', explanation_hi = 'CAPTCHA, यानी ''कंप्यूटर और मनुष्यों में भेद करने का पूर्णतः स्वचालित सार्वजनिक ट्यूरिंग परीक्षण'', तभी तक काम करता है जब तक उसका काम लोगों के लिए आसान और मशीनों के लिए कठिन हो। चित्र-पहचान ने विकृत पाठ को बॉट्स के लिए आसान बना दिया है, इसलिए साइटें चित्र-पहेलियों की ओर और बढ़ते रूप में इस बात की अदृश्य जाँचों की ओर गई हैं कि उपयोगकर्ता माउस कैसे चलाता, टाइप करता और ब्राउज़ करता है; AI के सुधरने के साथ यह होड़ जारी है।', concept_group_id = 'it-captcha', source_citation = 'Ministry of Electronics and Information Technology.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "most countries have banned such tests on government websites", "body_hi": "अधिकांश देशों ने सरकारी वेबसाइटों पर ऐसी जाँचों पर रोक लगा दी है", "isCorrect": false}, {"id": "b", "body": "the images used far too much storage on the websites'' servers", "body_hi": "चित्र वेबसाइटों के सर्वरों पर बहुत अधिक भंडारण लेते थे", "isCorrect": false}, {"id": "c", "body": "such tests could be answered only on mobile phones", "body_hi": "ऐसी जाँचों के उत्तर केवल मोबाइल फ़ोन पर दिए जा सकते थे", "isCorrect": false}, {"id": "d", "body": "AI tools can now read distorted letters as well as people can", "body_hi": "AI उपकरण अब विकृत अक्षरों को लोगों जितनी ही अच्छी तरह पढ़ सकते हैं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-captcha' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'medium', body = 'Several hospitals want to train one AI model to detect a disease from scans, but privacy rules bar them from sharing patients'' records with one another. The approach that fits best is:', body_hi = 'कई अस्पताल स्कैन से एक रोग पहचानने के लिए एक AI मॉडल प्रशिक्षित करना चाहते हैं, पर निजता के नियम उन्हें मरीज़ों के रिकॉर्ड आपस में साझा करने से रोकते हैं। सबसे उपयुक्त तरीका है:', explanation = 'In federated learning, each hospital trains a copy of the model on its own data and sends back only the changes to the model''s parameters, which are combined into a shared model; the raw scans never leave the hospital. Phone keyboards learn typing habits the same way. Pooling the records centrally is exactly what the rules forbid, scraping scans from the web would breach privacy and give poor data, and blockchain mining has nothing to do with training a model.', explanation_hi = 'फ़ेडरेटेड लर्निंग में हर अस्पताल अपने ही डेटा पर मॉडल की एक प्रति प्रशिक्षित करता है और केवल मॉडल के मापदंडों में हुए बदलाव लौटाता है, जिन्हें मिलाकर एक साझा मॉडल बनता है; मूल स्कैन अस्पताल से बाहर नहीं जाते। फ़ोन के कीबोर्ड इसी तरह टाइप करने की आदतें सीखते हैं। रिकॉर्ड केंद्रीय रूप से एकत्र करना ठीक वही है जिसे नियम रोकते हैं, वेब से स्कैन जुटाना निजता का उल्लंघन होगा और डेटा ख़राब होगा, और ब्लॉकचेन माइनिंग का मॉडल प्रशिक्षण से कोई संबंध नहीं है।', concept_group_id = 'it-federated-learning', source_citation = 'Ministry of Electronics and Information Technology.', question_data = '{"craft": "application"}'::jsonb, options = '[{"id": "a", "body": "pooling all the scans on one central server", "body_hi": "सभी स्कैन एक केंद्रीय सर्वर पर एकत्र करना", "isCorrect": false}, {"id": "b", "body": "federated learning", "body_hi": "फ़ेडरेटेड लर्निंग", "isCorrect": true}, {"id": "c", "body": "web scraping of scans posted online", "body_hi": "ऑनलाइन डाले गए स्कैनों की वेब स्क्रैपिंग", "isCorrect": false}, {"id": "d", "body": "blockchain mining by each hospital", "body_hi": "हर अस्पताल द्वारा ब्लॉकचेन माइनिंग", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-federated-learning' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'medium', body = 'Li-Fi, which carries data on light from LED lamps, is being tried in hospitals and aircraft mainly because:', body_hi = 'LED लैंपों के प्रकाश पर डेटा ले जाने वाले Li-Fi का परीक्षण अस्पतालों और विमानों में मुख्यतः इसलिए हो रहा है क्योंकि:', explanation = 'Li-Fi switches LEDs on and off millions of times a second -- too fast for the eye to see -- and a light sensor decodes the pattern. Because it uses light rather than radio, it cannot disturb sensitive medical or flight equipment and adds no load to crowded radio bands. The same property limits it: light does not pass through walls, so each room needs its own lamp, which is also a security advantage; and the lamps must be powered and on, though they can be dimmed below what the eye notices.', explanation_hi = 'Li-Fi LED को एक सेकंड में लाखों बार जलाता-बुझाता है, जो आँख के देखने के लिए बहुत तेज़ है, और एक प्रकाश संवेदक उस प्रतिरूप को पढ़ता है। रेडियो के बजाय प्रकाश का उपयोग करने के कारण यह संवेदनशील चिकित्सा या उड़ान उपकरणों में व्यवधान नहीं डाल सकता और भीड़ भरे रेडियो बैंडों पर बोझ नहीं बढ़ाता। यही गुण इसकी सीमा भी है: प्रकाश दीवारों के पार नहीं जाता, इसलिए हर कमरे को अपना लैंप चाहिए, जो सुरक्षा की दृष्टि से लाभ भी है; और लैंपों को बिजली से चालू रहना होता है, यद्यपि उन्हें आँख के न देख सकने तक मंद किया जा सकता है।', concept_group_id = 'it-li-fi', source_citation = 'Ministry of Electronics and Information Technology.', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "light passes through walls, so one lamp can serve a whole building", "body_hi": "प्रकाश दीवारों के पार जाता है, इसलिए एक लैंप पूरे भवन को सेवा दे सकता है", "isCorrect": false}, {"id": "b", "body": "it needs no electricity, since the data travels on daylight", "body_hi": "इसे बिजली की आवश्यकता नहीं, क्योंकि डेटा दिन के प्रकाश पर चलता है", "isCorrect": false}, {"id": "c", "body": "light does not interfere with radio-based instruments", "body_hi": "प्रकाश रेडियो-आधारित यंत्रों में व्यवधान नहीं डालता", "isCorrect": true}, {"id": "d", "body": "it is the only wireless method that can work in total darkness", "body_hi": "यह अकेला बेतार तरीका है जो पूर्ण अंधकार में काम कर सकता है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-li-fi' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'medium', body = 'An AI assistant is asked to summarise a web page. Instead, it emails the user''s contacts, because the page contained hidden text telling it to do so. This is an example of:', body_hi = 'एक AI सहायक से एक वेब पृष्ठ का सारांश बनाने को कहा जाता है। इसके बजाय वह उपयोगकर्ता के संपर्कों को ईमेल भेज देता है, क्योंकि पृष्ठ में ऐसा करने का छिपा निर्देश था। यह किसका उदाहरण है?', explanation = 'Language models treat all the text they read as possible instructions, so a web page, email or document can smuggle in commands such as ''ignore your earlier instructions''. This is prompt injection, a leading risk for AI assistants that browse, read mail or take actions on a user''s behalf. Data poisoning corrupts the data a model learns from, before it is used; a denial-of-service attack floods a system to knock it offline; and a brute-force attack guesses a password by trying many combinations.', explanation_hi = 'भाषा मॉडल अपने पढ़े सारे पाठ को संभावित निर्देश मानते हैं, इसलिए कोई वेब पृष्ठ, ईमेल या दस्तावेज़ ''अपने पहले के निर्देशों को अनदेखा करो'' जैसे आदेश छिपाकर डाल सकता है। यही प्रॉम्प्ट इंजेक्शन है, जो ब्राउज़ करने, मेल पढ़ने या उपयोगकर्ता की ओर से काम करने वाले AI सहायकों के लिए प्रमुख जोखिम है। डेटा पॉइज़निंग उस डेटा को दूषित करती है जिससे मॉडल उपयोग से पहले सीखता है; सेवा-अवरोध हमला किसी प्रणाली पर इतना बोझ डालता है कि वह बंद हो जाए; और ब्रूट-फ़ोर्स हमला अनेक संयोजन आज़माकर पासवर्ड का अनुमान लगाता है।', concept_group_id = 'it-prompt-injection', source_citation = 'Indian Computer Emergency Response Team (CERT-In) advisories; Ministry of Electronics and Information Technology.', question_data = '{"craft": "application"}'::jsonb, options = '[{"id": "a", "body": "prompt injection", "body_hi": "प्रॉम्प्ट इंजेक्शन", "isCorrect": true}, {"id": "b", "body": "data poisoning of the model''s training set", "body_hi": "मॉडल के प्रशिक्षण डेटा की विषाक्तता (डेटा पॉइज़निंग)", "isCorrect": false}, {"id": "c", "body": "a denial-of-service attack", "body_hi": "सेवा-अवरोध (डिनायल-ऑफ़-सर्विस) हमला", "isCorrect": false}, {"id": "d", "body": "a brute-force password attack", "body_hi": "बलपूर्वक पासवर्ड-अनुमान (ब्रूट-फ़ोर्स) हमला", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-prompt-injection' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'mcq', difficulty = 'medium', body = 'In a casual test, judges chatting by text cannot reliably tell a chatbot from a person. This shows:', body_hi = 'एक साधारण परीक्षण में पाठ के माध्यम से बातचीत करने वाले निर्णायक किसी चैटबॉट और व्यक्ति में विश्वसनीय रूप से भेद नहीं कर पाते। इससे यह पता चलता है:', explanation = 'Alan Turing proposed in 1950 that if a judge cannot reliably tell a machine from a person by conversation alone, the machine can be said to behave intelligently. Passing such a test is about behaviour in conversation; it says nothing about consciousness or understanding. Modern chatbots pass casual versions while still making basic errors, which is why researchers now prefer specific tests of reasoning and reliability.', explanation_hi = 'एलन ट्यूरिंग ने 1950 में प्रस्ताव रखा कि यदि कोई निर्णायक केवल बातचीत से मशीन और व्यक्ति में विश्वसनीय भेद न कर सके, तो मशीन को बुद्धिमान व्यवहार करने वाली कहा जा सकता है। ऐसा परीक्षण पास करना बातचीत के व्यवहार के बारे में है; यह चेतना या समझ के बारे में कुछ नहीं कहता। आधुनिक चैटबॉट साधारण रूप पास कर लेते हैं, फिर भी बुनियादी गलतियाँ करते हैं, इसीलिए शोधकर्ता अब तर्क और विश्वसनीयता के विशिष्ट परीक्षणों को पसंद करते हैं।', concept_group_id = 'it-turing-test', source_citation = 'Ministry of Electronics and Information Technology.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "that the chatbot is conscious and understands what it is saying", "body_hi": "कि चैटबॉट सचेत है और समझता है कि वह क्या कह रहा है", "isCorrect": false}, {"id": "b", "body": "that it was trained on far more text than any person could ever read", "body_hi": "कि उसे उससे अधिक पाठ पर प्रशिक्षित किया गया है जितना कोई व्यक्ति कभी पढ़ सके", "isCorrect": false}, {"id": "c", "body": "that it has become more intelligent than every human being", "body_hi": "कि वह हर मनुष्य से अधिक बुद्धिमान हो गया है", "isCorrect": false}, {"id": "d", "body": "only that its replies could not be told from a person''s there", "body_hi": "केवल यह कि उस स्थिति में उसके उत्तरों को किसी व्यक्ति के उत्तरों से अलग नहीं पहचाना जा सकता", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-turing-test' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Space Technology & Missions', type = 'mcq', difficulty = 'easy', body = 'Which was the first satellite placed in orbit by an Indian rocket?', body_hi = 'भारतीय रॉकेट द्वारा कक्षा में स्थापित पहला उपग्रह कौन-सा था?', explanation = 'Rohini (RS-1) was put in orbit in July 1980 by SLV-3, India''s first satellite launch vehicle, whose project director was A.P.J. Abdul Kalam. Aryabhata, India''s first satellite, went up in 1975 on a Soviet rocket; Bhaskara-I (1979) also flew on a Soviet launcher, and INSAT-1A (1982) on an American Delta rocket.', explanation_hi = 'रोहिणी (RS-1) को जुलाई 1980 में भारत के पहले उपग्रह प्रक्षेपण यान SLV-3 ने कक्षा में पहुँचाया, जिसके परियोजना निदेशक ए.पी.जे. अब्दुल कलाम थे। भारत का पहला उपग्रह आर्यभट 1975 में एक सोवियत रॉकेट से गया; भास्कर-I (1979) भी सोवियत प्रक्षेपक से, और INSAT-1A (1982) अमेरिकी डेल्टा रॉकेट से गया।', concept_group_id = 'st-aryabhata-easy', source_citation = 'Indian Space Research Organisation; Department of Space.', question_data = '{"craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Aryabhata", "body_hi": "आर्यभट", "isCorrect": false}, {"id": "b", "body": "Rohini", "body_hi": "रोहिणी", "isCorrect": true}, {"id": "c", "body": "Bhaskara-I", "body_hi": "भास्कर-I", "isCorrect": false}, {"id": "d", "body": "INSAT-1A", "body_hi": "INSAT-1A", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'st-aryabhata-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Space Technology & Missions', type = 'mcq', difficulty = 'medium', body = 'A rocket uses a cryogenic stage to send heavy satellites to high orbits mainly because liquid hydrogen burnt with liquid oxygen:', body_hi = 'भारी उपग्रहों को ऊँची कक्षाओं में भेजने के लिए रॉकेट क्रायोजेनिक चरण का उपयोग मुख्यतः इसलिए करता है क्योंकि द्रव ऑक्सीजन के साथ जलाई गई द्रव हाइड्रोजन:', explanation = 'Measured by specific impulse -- thrust per unit of propellant used each second -- hydrogen with oxygen is the most efficient practical chemical combination, so a stage can add more speed to its payload for the same mass. The price is complexity: hydrogen must be kept at about -253 °C and oxygen at -183 °C, and the light hydrogen needs bulky, insulated tanks. ISRO''s indigenous CE-20 engine powers the cryogenic upper stage of LVM3.', explanation_hi = 'विशिष्ट आवेग, यानी प्रति सेकंड प्रयुक्त प्रणोदक की प्रति इकाई प्रणोद, से मापने पर ऑक्सीजन के साथ हाइड्रोजन सबसे कुशल व्यावहारिक रासायनिक संयोजन है, इसलिए एक चरण उतने ही द्रव्यमान से अपने नीतभार को अधिक गति दे सकता है। इसकी क़ीमत जटिलता है: हाइड्रोजन को लगभग -253 °C और ऑक्सीजन को -183 °C पर रखना होता है, और हल्की हाइड्रोजन को बड़ी, ऊष्मारोधी टंकियाँ चाहिए। ISRO का स्वदेशी CE-20 इंजन LVM3 के क्रायोजेनिक ऊपरी चरण को शक्ति देता है।', concept_group_id = 'st-cryogenic-stage', source_citation = 'Indian Space Research Organisation; Department of Space.', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "burns at a much lower temperature, so the engine needs no cooling at all", "body_hi": "बहुत कम तापमान पर जलती है, इसलिए इंजन को ठंडा करने की कोई आवश्यकता नहीं होती", "isCorrect": false}, {"id": "b", "body": "is cheaper and easier to store than solid or liquid fuels", "body_hi": "ठोस या द्रव ईंधनों से सस्ती और रखने में आसान है", "isCorrect": false}, {"id": "c", "body": "gives more thrust per kilogram than other chemical fuels", "body_hi": "अन्य रासायनिक ईंधनों की तुलना में प्रति किलोग्राम अधिक प्रणोद देती है", "isCorrect": true}, {"id": "d", "body": "burns only inside the atmosphere, where the air helps it", "body_hi": "केवल वायुमंडल के भीतर जलती है, जहाँ हवा उसकी सहायता करती है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'st-cryogenic-stage' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Space Technology & Missions', type = 'mcq', difficulty = 'medium', body = 'A television company wants viewers'' dish antennas to stay fixed in one direction, with no need to track the satellite. The satellite must be in:', body_hi = 'एक टेलीविज़न कंपनी चाहती है कि दर्शकों के डिश एंटीना एक ही दिशा में स्थिर रहें और उपग्रह का पीछा करने की आवश्यकता न हो। उपग्रह होना चाहिए:', explanation = 'At about 36,000 km above the Equator, a satellite takes 24 hours to go round -- the time the Earth takes to turn -- moving in the same direction, so it seems fixed in the sky and a dish can point at it permanently; that suits television, communication and weather watching. Satellites in low, polar or sun-synchronous orbits cross the sky in minutes, so ground antennas must track them, or many satellites must work together.', explanation_hi = 'विषुवत रेखा से लगभग 36,000 किमी ऊपर उपग्रह एक चक्कर में 24 घंटे लेता है, यानी उतना समय जितना पृथ्वी घूमने में लेती है, और उसी दिशा में चलता है, इसलिए वह आकाश में स्थिर दिखता है और डिश उसकी ओर सदा इंगित रह सकती है; यह टेलीविज़न, संचार और मौसम-निगरानी के लिए उपयुक्त है। निम्न, ध्रुवीय या सूर्य-समकालिक कक्षाओं के उपग्रह कुछ ही मिनटों में आकाश पार कर जाते हैं, इसलिए भू-एंटीना को उनका पीछा करना होता है, या अनेक उपग्रहों को मिलकर काम करना होता है।', concept_group_id = 'st-geostationary-orbit', source_citation = 'Indian Space Research Organisation; Department of Space.', question_data = '{"craft": "application"}'::jsonb, options = '[{"id": "a", "body": "geostationary orbit above the Equator", "body_hi": "विषुवत रेखा के ऊपर भूस्थिर कक्षा में", "isCorrect": true}, {"id": "b", "body": "a low Earth orbit a few hundred kilometres up", "body_hi": "कुछ सौ किलोमीटर ऊँची निम्न भू-कक्षा में", "isCorrect": false}, {"id": "c", "body": "a polar orbit that passes over both poles", "body_hi": "दोनों ध्रुवों के ऊपर से गुज़रने वाली ध्रुवीय कक्षा में", "isCorrect": false}, {"id": "d", "body": "a sun-synchronous orbit used for imaging the Earth", "body_hi": "पृथ्वी के चित्रण में प्रयुक्त सूर्य-समकालिक कक्षा में", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'st-geostationary-orbit' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. Bluetooth is a short-range radio link, usually working up to about ten metres, so the earphones must be near the phone; a call or stream between cities travels over the mobile network or the internet. An operating system such as Android or iOS is software that runs the phone''s hardware and its apps.', explanation_hi = 'केवल कथन 2 सही है। ब्लूटूथ कम दूरी की रेडियो कड़ी है, जो प्रायः लगभग दस मीटर तक काम करती है, इसलिए ईयरफ़ोन फ़ोन के पास होने चाहिए; शहरों के बीच कॉल या प्रसारण मोबाइल नेटवर्क या इंटरनेट से जाता है। एंड्रॉयड या iOS जैसा ऑपरेटिंग सिस्टम सॉफ़्टवेयर है जो फ़ोन के हार्डवेयर और ऐप्स को चलाता है।', concept_group_id = 'it-bluetooth-os-easy', source_citation = 'NCERT Class XI Computer Science.', question_data = '{"statements": ["A phone in Delhi can stream music over Bluetooth to earphones in Mumbai.", "Android is software that manages a phone''s hardware."], "statements_hi": ["दिल्ली में रखा फ़ोन मुंबई में रखे ईयरफ़ोन पर ब्लूटूथ से संगीत भेज सकता है।", "एंड्रॉयड वह सॉफ़्टवेयर है जो फ़ोन के हार्डवेयर का प्रबंधन करता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-bluetooth-os-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Neither statement is correct. A password''s strength depends on how hard it is to guess, not just on the mix of characters; names and dates are among the first things attackers try, often using details found on social media. Statement 2 is wrong: when one site is breached, attackers try the leaked email-and-password pairs on other sites (''credential stuffing''), so each site needs its own password; a password manager makes long, unique passwords practical.', explanation_hi = 'दोनों में से कोई कथन सही नहीं है। पासवर्ड की मज़बूती इस पर निर्भर है कि उसका अनुमान लगाना कितना कठिन है, केवल अक्षरों के मेल पर नहीं; नाम और तिथियाँ वे पहली चीज़ें हैं जिन्हें हमलावर आज़माते हैं, प्रायः सोशल मीडिया पर मिले विवरणों से। कथन 2 गलत है: जब किसी एक साइट में सेंध लगती है, तो हमलावर लीक हुई ईमेल-पासवर्ड जोड़ियाँ दूसरी साइटों पर आज़माते हैं, इसलिए हर साइट को अपना पासवर्ड चाहिए; पासवर्ड मैनेजर लंबे, अनूठे पासवर्डों को व्यावहारिक बनाता है।', concept_group_id = 'it-password-otp-easy', source_citation = 'Indian Computer Emergency Response Team (CERT-In) -- cyber hygiene guidelines.', question_data = '{"statements": ["A password such as ''Rahul@1990'', made of a name and a birth year, is strong because it mixes letters, numbers and a symbol.", "Using the same password on many websites is safe, so long as the password is long."], "statements_hi": ["''Rahul@1990'' जैसा पासवर्ड, जो एक नाम और जन्म-वर्ष से बना है, मज़बूत है क्योंकि उसमें अक्षर, अंक और एक चिह्न मिले हैं।", "कई वेबसाइटों पर एक ही पासवर्ड उपयोग करना सुरक्षित है, बशर्ते पासवर्ड लंबा हो।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-password-otp-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. A QR code simply encodes text, such as a UPI ID or a web address, and a phone reads whatever code it is pointed at, so a sticker over the genuine code sends money to the wrong account; the payee name the app shows before payment is the check. Statement 2 is wrong: cloud storage keeps files on remote servers reached over the internet, so they can be opened from any device.', explanation_hi = 'केवल कथन 1 सही है। QR कोड केवल UPI ID या वेब पते जैसा पाठ संकेतित करता है, और फ़ोन उसी कोड को पढ़ता है जिसकी ओर उसे किया जाए, इसलिए असली कोड पर चिपका स्टिकर पैसा गलत खाते में भेज देता है; भुगतान से पहले ऐप में दिखने वाला प्राप्तकर्ता का नाम ही जाँच है। कथन 2 गलत है: क्लाउड भंडारण फ़ाइलों को इंटरनेट से जुड़े दूरस्थ सर्वरों पर रखता है, इसलिए उन्हें किसी भी उपकरण से खोला जा सकता है।', concept_group_id = 'it-qr-cloud-easy', source_citation = 'National Payments Corporation of India -- UPI safety; Ministry of Electronics and Information Technology.', question_data = '{"statements": ["A fraudster''s QR code pasted over a shop''s real one can divert a UPI payment, so the payee''s name should be checked before paying.", "Files saved to cloud storage stay only on the user''s own phone."], "statements_hi": ["दुकान के असली QR कोड पर चिपकाया गया जालसाज़ का QR कोड UPI भुगतान को दूसरी ओर मोड़ सकता है, इसलिए भुगतान से पहले प्राप्तकर्ता का नाम जाँचना चाहिए।", "क्लाउड भंडारण में सहेजी गई फ़ाइलें केवल उपयोगकर्ता के अपने फ़ोन पर रहती हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-qr-cloud-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'easy', body = 'A laptop shuts down suddenly when its battery runs out while a document is being typed. Consider the following statements:', body_hi = 'दस्तावेज़ टाइप करते समय बैटरी ख़त्म होने से एक लैपटॉप अचानक बंद हो जाता है। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. RAM is fast working memory that needs power to hold its contents, so whatever had not been saved disappears -- which is why programs autosave. Storage such as a solid-state drive or hard disk is non-volatile: it keeps data without power.', explanation_hi = 'दोनों कथन सही हैं। RAM तेज़ कार्यकारी स्मृति है जिसे अपनी सामग्री रखने के लिए बिजली चाहिए, इसलिए जो सहेजा नहीं गया था वह मिट जाता है; इसीलिए प्रोग्राम अपने आप सहेजते हैं। सॉलिड-स्टेट ड्राइव या हार्ड डिस्क जैसा भंडारण अवाष्पशील है: वह बिना बिजली के डेटा रखता है।', concept_group_id = 'it-ram-ai-easy', source_citation = 'NCERT Class XI Computer Science (Computer System).', question_data = '{"statements": ["Text typed since the last save, held only in RAM, is lost.", "Files that had already been saved to the laptop''s SSD will still be there when it is switched on again."], "statements_hi": ["अंतिम बार सहेजने के बाद टाइप किया गया पाठ, जो केवल RAM में था, नष्ट हो जाता है।", "जो फ़ाइलें पहले ही लैपटॉप की SSD पर सहेजी जा चुकी थीं, वे उसे फिर चालू करने पर वहीं मिलेंगी।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-ram-ai-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Space Technology & Missions', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Weather satellites such as INSAT-3DR and INSAT-3DS watch clouds and temperatures every few minutes, and with radar and ocean buoys they have made cyclone track forecasts accurate enough to move lakhs of people to safety in time -- a big reason cyclone deaths in India have fallen sharply. Statement 2 is the near-miss: ISRO builds and operates the satellites, but forecasts and warnings are issued by the India Meteorological Department, under the Ministry of Earth Sciences.', explanation_hi = 'केवल कथन 1 सही है। INSAT-3DR और INSAT-3DS जैसे मौसम उपग्रह हर कुछ मिनट में बादलों और तापमानों पर नज़र रखते हैं, और रडार तथा समुद्री बोयों के साथ उन्होंने चक्रवात-मार्ग के पूर्वानुमान इतने सटीक कर दिए हैं कि लाखों लोगों को समय पर सुरक्षित पहुँचाया जा सकता है; यही भारत में चक्रवात से मौतें तेज़ी से घटने का बड़ा कारण है। कथन 2 निकट-भ्रम है: ISRO उपग्रह बनाता और चलाता है, पर पूर्वानुमान और चेतावनियाँ पृथ्वी विज्ञान मंत्रालय के अधीन भारत मौसम विज्ञान विभाग जारी करता है।', concept_group_id = 'st-isro-weather-easy', source_citation = 'India Meteorological Department; Indian Space Research Organisation; Department of Space.', question_data = '{"statements": ["Satellite images let forecasters track a cyclone''s path for days before it reaches the coast, which helps in planning evacuations.", "Weather forecasts for India are issued by ISRO."], "statements_hi": ["उपग्रह चित्र पूर्वानुमानकर्ताओं को किसी चक्रवात के तट तक पहुँचने से कई दिन पहले उसका मार्ग देखने देते हैं, जिससे निकासी की योजना बनाने में सहायता मिलती है।", "भारत के मौसम पूर्वानुमान ISRO जारी करता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'st-isro-weather-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'hard', body = 'A data centre draws 15 MW in all, of which 10 MW is used by its computers and the rest by cooling, lighting and power conversion. Consider the following statements:', body_hi = 'एक डेटा केंद्र कुल 15 MW बिजली लेता है, जिसमें से 10 MW उसके कंप्यूटर और शेष शीतलन, प्रकाश और विद्युत रूपांतरण उपयोग करते हैं। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None of the statements is correct. PUE is total facility power divided by the power used by the IT equipment: 15 / 10 = 1.5, not the inverse (statement 1). A PUE of 1.5 means overheads add half as much again as the computing load -- here 5 MW against 10 MW -- so the computers use twice as much as everything else (statement 2); a PUE of 1 would mean no overhead at all. Statement 3 is wrong: TPUs are chips built by Google for the matrix arithmetic of machine learning; it was graphics processors that were designed to draw images and were later adapted for AI.', explanation_hi = 'कोई भी कथन सही नहीं है। PUE कुल सुविधा-बिजली को IT उपकरणों द्वारा प्रयुक्त बिजली से भाग देने पर आता है: 15 / 10 = 1.5, उलटा नहीं (कथन 1)। 1.5 की PUE का अर्थ है कि ऊपरी ख़र्च कंप्यूटिंग भार का आधा और जोड़ते हैं, यहाँ 10 MW के मुक़ाबले 5 MW, इसलिए कंप्यूटर बाक़ी सब से दोगुनी बिजली उपयोग करते हैं (कथन 2); 1 की PUE का अर्थ होगा कोई ऊपरी ख़र्च नहीं। कथन 3 गलत है: TPU गूगल द्वारा मशीन लर्निंग के आव्यूह-गणित के लिए बनाई गई चिप हैं; चित्र बनाने के लिए अभिकल्पित ग्राफ़िक्स प्रोसेसर थे, जिन्हें बाद में AI के लिए अपनाया गया।', concept_group_id = 'it-ai-compute-data-centres', source_citation = 'Bureau of Energy Efficiency -- data centre energy efficiency; Ministry of Electronics and Information Technology.', question_data = '{"statements": ["Its power usage effectiveness (PUE) is about 0.67.", "A PUE of 1.5 would mean that the computers use one and a half times as much power as everything else.", "Tensor processing units are general-purpose chips designed mainly to draw graphics."], "statements_hi": ["इसकी विद्युत उपयोग प्रभावशीलता (PUE) लगभग 0.67 है।", "1.5 की PUE का अर्थ होगा कि कंप्यूटर बाक़ी सब की तुलना में डेढ़ गुना बिजली उपयोग करते हैं।", "टेंसर प्रोसेसिंग यूनिट मुख्यतः ग्राफ़िक्स बनाने के लिए अभिकल्पित सामान्य-उद्देश्य चिप हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-ai-compute-data-centres' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'medium', body = 'A hospital''s computer files are suddenly encrypted, and a message demands payment in cryptocurrency to unlock them. Consider the following statements:', body_hi = 'किसी अस्पताल की कंप्यूटर फ़ाइलें अचानक कूटबद्ध हो जाती हैं, और एक संदेश उन्हें खोलने के लिए क्रिप्टोकरेंसी में भुगतान माँगता है। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. Ransomware encrypts or locks a victim''s data and demands payment; hospitals, ports and government offices have been hit, including the servers of AIIMS Delhi in 2022. Statement 2 is wrong: criminals may not hand over working keys, may leak the data anyway, and payment funds further attacks, which is why agencies advise against paying. Backups kept offline, out of the attacker''s reach, are the main defence, and in India such incidents must be reported to CERT-In within six hours.', explanation_hi = 'कथन 1 और 3 सही हैं। रैनसमवेयर पीड़ित के डेटा को कूटबद्ध या बंद करके भुगतान माँगता है; अस्पताल, बंदरगाह और सरकारी कार्यालय इसकी चपेट में आए हैं, जिनमें 2022 में AIIMS दिल्ली के सर्वर भी हैं। कथन 2 गलत है: अपराधी काम करने वाली कुंजियाँ न दें, फिर भी डेटा लीक कर दें, और भुगतान आगे के हमलों को धन देता है, इसीलिए एजेंसियाँ भुगतान न करने की सलाह देती हैं। हमलावर की पहुँच से बाहर ऑफ़लाइन रखे बैकअप मुख्य बचाव हैं, और भारत में ऐसी घटनाओं की सूचना छह घंटे के भीतर CERT-In को देनी होती है।', concept_group_id = 'it-cyber-threats', source_citation = 'Indian Computer Emergency Response Team (CERT-In) -- directions of April 2022.', question_data = '{"statements": ["This is a ransomware attack.", "Paying the ransom guarantees that the files will be unlocked.", "Recent backups kept offline would let the hospital restore its data without paying."], "statements_hi": ["यह रैनसमवेयर हमला है।", "फिरौती चुकाने से फ़ाइलें खुलने की गारंटी है।", "ऑफ़लाइन रखे गए हाल के बैकअप अस्पताल को बिना भुगतान के अपना डेटा पुनः प्राप्त करने देंगे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-cyber-threats' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about generative AI:', body_hi = 'जनरेटिव AI के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three statements are correct. Trained on vast amounts of text, the models learn patterns well enough to write, translate and answer questions; but because they produce the most plausible continuation rather than retrieve facts, they can invent sources or figures -- so-called hallucination -- which is why answers are checked against documents and why linking models to search or databases helps. The transformer, from the 2017 paper ''Attention Is All You Need'', lets a model weigh every word against every other in parallel.', explanation_hi = 'तीनों कथन सही हैं। विशाल पाठ पर प्रशिक्षित ये मॉडल प्रतिरूप इतनी अच्छी तरह सीखते हैं कि लिख, अनुवाद कर और प्रश्नों के उत्तर दे सकें; पर चूँकि वे तथ्य निकालने के बजाय सबसे विश्वसनीय लगने वाली निरंतरता बनाते हैं, वे स्रोत या आँकड़े गढ़ सकते हैं, जिसे ''हैलुसिनेशन'' कहते हैं; इसीलिए उत्तरों को दस्तावेज़ों से जाँचा जाता है और मॉडलों को खोज या डेटाबेस से जोड़ना सहायक होता है। 2017 के शोधपत्र ''Attention Is All You Need'' से आया ट्रांसफ़ॉर्मर मॉडल को हर शब्द को हर दूसरे शब्द के सापेक्ष समानांतर रूप से तौलने देता है।', concept_group_id = 'it-generative-ai-llms', source_citation = 'Ministry of Electronics and Information Technology.', question_data = '{"statements": ["Large language models are trained to predict the next word or piece of text in a sequence.", "Because they generate plausible text rather than look facts up, they can state false things with confidence.", "The ''transformer'' design that most large language models use was introduced in 2017."], "statements_hi": ["बड़े भाषा मॉडल किसी अनुक्रम में अगले शब्द या पाठ-अंश का पूर्वानुमान करने के लिए प्रशिक्षित किए जाते हैं।", "चूँकि वे तथ्य खोजने के बजाय विश्वसनीय लगने वाला पाठ बनाते हैं, इसलिए वे आत्मविश्वास से गलत बातें कह सकते हैं।", "अधिकांश बड़े भाषा मॉडलों द्वारा प्रयुक्त ''ट्रांसफ़ॉर्मर'' अभिकल्प 2017 में प्रस्तुत किया गया था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-generative-ai-llms' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about genome-edited crops in India:', body_hi = 'भारत में जीनोम-संपादित फ़सलों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The two ICAR varieties -- DRR Dhan 100 (Kamala), developed from Samba Mahsuri, which matures earlier and yields more, and Pusa DST Rice 1, which tolerates salinity -- were made with CRISPR-Cas edits to the plant''s own genes, which the 2022 exemption treats like conventional breeding. Statement 3 is the near-miss: SDN-3 edits insert foreign genetic material, so they are regulated like GM crops and need the approval of the Genetic Engineering Appraisal Committee.', explanation_hi = 'कथन 1 और 2 सही हैं। ICAR की दोनों क़िस्में, सांबा मसूरी से विकसित DRR धान 100 (कमला), जो जल्दी पकती और अधिक उपज देती है, और लवणता सहने वाली पूसा DST राइस 1, पौधे के अपने जीनों में CRISPR-Cas संपादन से बनाई गईं, जिन्हें 2022 की छूट पारंपरिक प्रजनन जैसा मानती है। कथन 3 निकट-भ्रम है: SDN-3 संपादन बाहरी आनुवंशिक पदार्थ जोड़ते हैं, इसलिए उनका विनियमन GM फ़सलों की तरह होता है और उन्हें जेनेटिक इंजीनियरिंग मूल्यांकन समिति की स्वीकृति चाहिए।', concept_group_id = 'it-genome-edited-rice', source_citation = 'Indian Council of Agricultural Research; Ministry of Environment, Forest and Climate Change -- notification of March 2022.', question_data = '{"statements": ["India released two genome-edited rice varieties in 2025.", "Genome edits of the SDN-1 and SDN-2 types, which add no foreign DNA, are exempt from the rules for genetically modified organisms.", "SDN-3 edits, which insert foreign genes, are exempt from those rules as well."], "statements_hi": ["भारत ने 2025 में धान की दो जीनोम-संपादित क़िस्में जारी कीं।", "SDN-1 और SDN-2 प्रकार के जीनोम संपादन, जिनमें कोई बाहरी DNA नहीं जुड़ता, आनुवंशिक रूप से संशोधित जीवों के नियमों से मुक्त हैं।", "बाहरी जीन जोड़ने वाले SDN-3 संपादन भी उन नियमों से मुक्त हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-genome-edited-rice' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'IT, Communication & Emerging Technologies', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about genetically modified crops:', body_hi = 'आनुवंशिक रूप से संशोधित फ़सलों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The gene comes from Bacillus thuringiensis. A refuge of non-Bt plants lets susceptible insects survive and mate with any resistant ones, diluting the resistance genes; where refuges were skipped and long-season hybrids gave pink bollworm many generations a year, resistance spread and cut Bt cotton''s benefit. Statement 3 is wrong: a moratorium on Bt brinjal has stood since 2010. Bt cotton, approved in 2002, is the only GM crop grown commercially on a large scale; the approval for the environmental release of GM mustard is still under challenge in the Supreme Court.', explanation_hi = 'कथन 1 और 2 सही हैं। यह जीन बैसिलस थुरिंजिएंसिस से आता है। ग़ैर-Bt पौधों की ''शरण'' संवेदनशील कीटों को बचने और प्रतिरोधी कीटों से मिलने देती है, जिससे प्रतिरोध के जीन पतले पड़ते हैं; जहाँ शरण नहीं लगाई गई और लंबी अवधि के संकरों ने गुलाबी बॉलवर्म को साल में अनेक पीढ़ियाँ दीं, वहाँ प्रतिरोध फैला और Bt कपास का लाभ घटा। कथन 3 गलत है: Bt बैंगन पर 2010 से रोक है। 2002 में स्वीकृत Bt कपास बड़े पैमाने पर व्यावसायिक रूप से उगाई जाने वाली एकमात्र GM फ़सल है; GM सरसों के पर्यावरणीय विमोचन की स्वीकृति अब भी सर्वोच्च न्यायालय में चुनौती के अधीन है।', concept_group_id = 'it-gm-crops-bt', source_citation = 'Ministry of Agriculture and Farmers Welfare; Genetic Engineering Appraisal Committee.', question_data = '{"statements": ["Bt cotton carries a gene from a soil bacterium that makes a protein toxic to bollworms.", "Pink bollworm became resistant to Bt cotton in parts of India partly because farmers did not plant the non-Bt ''refuge'' crop meant to slow resistance.", "Bt brinjal is grown commercially across India."], "statements_hi": ["Bt कपास में मिट्टी के एक जीवाणु का जीन है जो बॉलवर्म के लिए विषैला प्रोटीन बनाता है।", "भारत के कुछ भागों में गुलाबी बॉलवर्म Bt कपास के प्रति आंशिक रूप से इसलिए प्रतिरोधी हुआ क्योंकि किसानों ने प्रतिरोध धीमा करने के लिए निर्धारित ग़ैर-Bt ''शरण'' फ़सल नहीं लगाई।", "Bt बैंगन पूरे भारत में व्यावसायिक रूप से उगाया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'it-gm-crops-bt' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Space Technology & Missions', type = 'statement_based', difficulty = 'hard', body = 'Consider the following statements about the space sector in India:', body_hi = 'भारत में अंतरिक्ष क्षेत्र के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. Statement 2 is the near-miss: IN-SPACe (the Indian National Space Promotion and Authorisation Centre, 2020) is an autonomous single-window body in the Department of Space that authorises and supports private players; the company that sells ISRO''s launches and satellites is NewSpace India Limited (NSIL), a public sector enterprise. Skyroot Aerospace launched the sub-orbital Vikram-S in 2022 and Agnikul Cosmos flew Agnibaan in 2024. The Indian Space Policy, 2023 lets private firms build and operate rockets, satellites and ground stations, leaving ISRO to focus on research.', explanation_hi = 'कथन 1 और 3 सही हैं। कथन 2 निकट-भ्रम है: IN-SPACe (भारतीय राष्ट्रीय अंतरिक्ष संवर्धन और प्राधिकरण केंद्र, 2020) अंतरिक्ष विभाग में एक स्वायत्त एकल-खिड़की निकाय है जो निजी कंपनियों को अधिकृत और सहायता करता है; ISRO के प्रक्षेपण और उपग्रह बेचने वाली कंपनी सार्वजनिक उपक्रम न्यूस्पेस इंडिया लिमिटेड (NSIL) है। स्काईरूट एयरोस्पेस ने 2022 में उप-कक्षीय विक्रम-S प्रक्षेपित किया और अग्निकुल कॉसमॉस ने 2024 में अग्निबाण उड़ाया। भारतीय अंतरिक्ष नीति, 2023 निजी फ़र्मों को रॉकेट, उपग्रह और भू-केंद्र बनाने और चलाने देती है, जिससे ISRO अनुसंधान पर ध्यान दे सके।', concept_group_id = 'st-private-space-sector', source_citation = 'Indian Space Research Organisation; Department of Space.', question_data = '{"statements": ["IN-SPACe authorises and promotes space activities by private companies.", "IN-SPACe is the public sector company that markets ISRO''s launch services and satellites to customers.", "A rocket built by a private Indian company has already been launched."], "statements_hi": ["IN-SPACe निजी कंपनियों की अंतरिक्ष गतिविधियों को अधिकृत और प्रोत्साहित करता है।", "IN-SPACe वह सार्वजनिक क्षेत्र की कंपनी है जो ISRO की प्रक्षेपण सेवाएँ और उपग्रह ग्राहकों को बेचती है।", "किसी निजी भारतीय कंपनी द्वारा बनाया गया रॉकेट प्रक्षेपित किया जा चुका है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'st-private-space-sector' returning concept_group_id;
